removed_apples = inventory.pop("apples")
del inventory["oranges"]

print("Inventory:", inventory)
print("Removed apples:", removed_apples)"},"pair":{"html":"","css":"","js":"","python":"inventory = {"apples": 4, "bananas": 6}

