del inventory["oranges"]

print("Inventory:", inventory)
print("Removed apples:", removed_apples)"},"hints":[{"tier":"nudge","text":"update() can change an existing value and add a new key. pop() removes a key and gives back its value."},{"tier":"nudge","text":"Save the result of inventory.pop("apples") in removed_apples before using del on oranges."},{"tier":"approach","text":"Use inventory.update({"bananas": 8, "oranges": 3}), then removed_apples = inventory.pop("apples"), followed by del inventory["oranges"]."}],"review":[{"type":"good","text":"You used update(), pop(), and del to change the dictionary in three different ways."},{"type":"tip","text":"Remember that pop() can return the value it removes, which is useful when you need to display it later."}],"guideSteps":[{"explain":"Create an inventory dictionary with two items and their quantities.","label":"Create the inventory","code":"inventory = {"apples": 4, "bananas": 6}"},{"explain":"Use update() to replace the banana quantity and add oranges.","label":"Update items","code":"inventory = {"apples": 4, "bananas": 6}

