del inventory["oranges"]

print("Inventory:", inventory)
print("Removed apples:", removed_apples)"}],"blooms_level":"Applying","difficulty_level":"medium","difficulty_rating":5,"questionType":"code_challenge","visualMatchThreshold":90,"metadata":{"subject":"Python","courseLevel":"Level 1","module":"Sets and Dictionaries","topic":"Sets and Dictionaries","topicType":"Concept","topicFamily":"Sets and Dictionaries","subtopic":"Dictionary basics","learning_objective":"Use update(), pop() and del to mutate a dictionary.","bloomsVerb":"Use","cognitiveTier":"Lower-Order","skillArea":"mixed"}}

{"title":"Explore a Classroom Inventory","lesson":"L1 · Sets and Dictionaries · Iterating over dictionaries","desc":"Create a dictionary of classroom supplies and use <code>.keys()</code>, <code>.values()</code>, and <code>.items()</code> to print the item names, quantities, and matching item-quantity pairs.","startFile":"python","goals":[{"id":"uses-keys","label":"Iterates over dictionary keys","target":"python","kind":"regex","rule":"\.keys\s*\(","flags":"i","minCount":1},{"id":"uses-values","label":"Iterates over dictionary values","target":"python","kind":"regex","rule":"\.values\s*\(","flags":"i","minCount":1},{"id":"uses-items","label":"Iterates over dictionary items","target":"python","kind":"regex","rule":"\.items\s*\(","flags":"i","minCount":1},{"id":"prints-results","label":"Prints the inventory results","target":"python","kind":"regex","rule":"print\s*\(","flags":"i","minCount":3}],"targetHtml":"<pre><code>Item names:
