for n in (2, 4, 8):
    print(f"n = {n}, operations = {count_operations(n)}")"},{"explain":"Because the inner loop runs n times for each of n outer-loop iterations, the predicted complexity is O(n²).","label":"Print the prediction","code":"def count_operations(n):
    operations = 0

