# 👈 YOUR CODE: calculate the order total and print the receipt."},"solo":{"html":"","css":"","js":"","python":""}},"solution":{"html":"","css":"","js":"","python":"def calculate_item_total(price, quantity):
    return price * quantity


def calculate_order_total(item_totals):
    return sum(item_totals)


def print_receipt(item_names, item_totals, total):
    print("Snack Stand Receipt")
    for name, item_total in zip(item_names, item_totals):
        print(f"{name}: ${item_total:.2f}")
    print(f"Total: ${total:.2f}")


item_names = ["Popcorn", "Juice", "Fruit cup"]
prices = [2.50, 1.50, 3.00]
quantities = [2, 3, 1]

item_totals = []
for price, quantity in zip(prices, quantities):
    item_totals.append(calculate_item_total(price, quantity))

total = calculate_order_total(item_totals)
