{"title":"Rectangle Area Property","lesson":"L2 · Object-Oriented Programming 2 · Encapsulation hints","desc":"Create a <code>Rectangle</code> class with private width and height attributes. Use <code>@property</code> to expose a computed <code>area</code> attribute, then print the rectangle's area.","startFile":"python","goals":[{"id":"creates-rectangle-class","label":"Creates a Rectangle class","target":"python","kind":"regex","rule":"class\s+Rectangle","flags":"i","minCount":1},{"id":"uses-property-decorator","label":"Uses the @property decorator","target":"python","kind":"regex","rule":"@property","flags":"i","minCount":1},{"id":"defines-area-property","label":"Defines an area property","target":"python","kind":"regex","rule":"def\s+area\s*\(\s*self\s*\)","flags":"i","minCount":1},{"id":"computes-area","label":"Computes area from width and height","target":"python","kind":"regex","rule":"return\s+self\._width\s*\*\s+self\._height","flags":"i","minCount":1}],"targetHtml":"<pre><code>Area: 24</code></pre>","targetSub":"The computed area is displayed using the property.","files":{"guide":{"html":"","css":"","js":"","python":"class Rectangle:
    def __init__(self, width, height):
        self._width = width
        self._height = height

    @property
    def area(self):
        return self._width * self._height


rectangle = Rectangle(6, 4)
print("Area:", rectangle.area)"},"pair":{"html":"","css":"","js":"","python":"class Rectangle:
    def __init__(self, width, height):
        self._width = width
        self._height = height

    # 👈 YOUR CODE: add an @property named area that returns width * height


rectangle = Rectangle(6, 4)
print("Area:", rectangle.area)"},"solo":{"html":"","css":"","js":"","python":""}},"solution":{"html":"","css":"","js":"","python":"class Rectangle:
    def __init__(self, width, height):
        self._width = width
        self._height = height

